STEPS = {"m": 1, "M": 2, "A": 3}


class Scale:
    def __init__(self, tonic):
        self.tonic = tonic[0].upper() + tonic[1:]
        notes = FLATS if tonic in FLAT_TONICS else SHARPS
        start = notes.index(self.tonic)
        self.notes = notes[start:] + notes[:start]

    def chromatic(self):
        return list(self.notes)

    def interval(self, intervals):
        result = [self.notes[0]]
        position = 0
        for step in intervals:
            position += STEPS[step]
            result.append(self.notes[position % 12])
        return result
